using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class YachtSurfaceRepair {
const string D="Assets/Scenes/Oasis/YachtPortAtlas";static HashSet<Mesh> seen=new HashSet<Mesh>();static int flipped,meshes;static YachtSurfaceRepair(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("YachtSurfaceRepair.request"))return;File.Delete("YachtSurfaceRepair.request");Run();}
static void Repair(MeshFilter filter){var mesh=filter.sharedMesh;if(!seen.Add(mesh))return;var p=mesh.vertices;var indices=mesh.triangles;var tiles=new List<Vector4>();mesh.GetUVs(1,tiles);var colors=mesh.colors;var parent=Enumerable.Range(0,p.Length).ToArray();Func<int,int> find=null;find=i=>parent[i]==i?i:parent[i]=find(parent[i]);var weld=new Dictionary<Vector3Int,int>();for(int i=0;i<p.Length;i++){var key=new Vector3Int(Mathf.RoundToInt(p[i].x*1000),Mathf.RoundToInt(p[i].y*1000),Mathf.RoundToInt(p[i].z*1000));if(weld.TryGetValue(key,out int old))parent[find(i)]=find(old);else weld[key]=i;}for(int i=0;i<indices.Length;i+=3){parent[find(indices[i+1])]=find(indices[i]);parent[find(indices[i+2])]=find(indices[i]);}var sums=new Dictionary<int,Vector3>();var counts=new Dictionary<int,int>();for(int i=0;i<p.Length;i++){int root=find(i);if(!sums.ContainsKey(root)){sums[root]=Vector3.zero;counts[root]=0;}sums[root]+=p[i];counts[root]++;}var points=new List<Vector3>();var normals=new List<Vector3>();var uv=new List<Vector2>();var flags=new List<Vector4>();var cc=new List<Color>();var ids=new List<int>();for(int i=0;i<indices.Length;i+=3){int a=indices[i],b=indices[i+1],c=indices[i+2];var n=Vector3.Cross(p[b]-p[a],p[c]-p[a]).normalized;var face=(p[a]+p[b]+p[c])/3;var center=sums[find(a)]/counts[find(a)];bool ring=tiles[a].x<0&&colors[a].r>colors[a].g*2;if(!ring&&Vector3.Dot(n,face-center)<-.00001f){int t=b;b=c;c=t;n=-n;flipped++;}var wn=filter.transform.TransformDirection(n).normalized;bool top=Mathf.Abs(wn.y)>.65f;bool wood=tiles[a].x==0;var tile=tiles[a];tile.z=wood&&!top?1:0;int first=points.Count;foreach(int j in new[]{a,b,c}){var world=filter.transform.TransformPoint(p[j]);Vector2 tex=top?new Vector2(world.x*.5f,world.z*.5f):Mathf.Abs(wn.x)>Mathf.Abs(wn.z)?new Vector2(world.z*.8f,world.y*.8f):new Vector2(world.x*.8f,world.y*.8f);if(wood&&!top)tex=new Vector2(world.y*.8f,Mathf.Abs(wn.x)>Mathf.Abs(wn.z)?world.z*.5f:world.x*.5f);points.Add(p[j]);normals.Add(n);uv.Add(tex);flags.Add(tile);cc.Add(colors[j]);}ids.AddRange(new[]{first,first+1,first+2});}mesh.Clear();mesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mesh.SetVertices(points);mesh.SetTriangles(ids,0);mesh.SetNormals(normals);mesh.SetUVs(0,uv);mesh.SetUVs(1,flags);mesh.SetColors(cc);mesh.RecalculateBounds();mesh.name+=" Correct outward faces and UVs";EditorUtility.SetDirty(mesh);meshes++;}
static void Run(){try{foreach(string path in Enumerable.Range(1,6).Select(i=>"Assets/Scenes/Oasis/SouthBeach/Docking Pier "+i+".prefab").Concat(new[]{D+"/Yatch Port Edge Details.prefab"})){var prefab=PrefabUtility.LoadPrefabContents(path);foreach(var filter in prefab.GetComponentsInChildren<MeshFilter>())Repair(filter);foreach(var lod in prefab.GetComponentsInChildren<LODGroup>())lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(prefab,path);PrefabUtility.UnloadPrefabContents(prefab);}AssetDatabase.SaveAssets();var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var yard=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads").GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Yatch_Port");var standalone=UnityEngine.Object.Instantiate(yard.gameObject);standalone.name="Yatch_Port";PrefabUtility.SaveAsPrefabAsset(standalone,D+"/Yatch_Port Detailed.prefab");UnityEngine.Object.DestroyImmediate(standalone);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var docks=scene.GetRootGameObjects().Single(g=>g.name=="South Beach Bays and Docking Piers");var pier=docks.transform.GetChild(2);var target=pier.TransformPoint(new Vector3(0,1,36));typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,target+pier.TransformDirection(new Vector3(7,3,-11)),target+pier.forward*8,"Corrected-Dock-Faces-and-Texture"});var material=AssetDatabase.LoadAssetAtPath<Material>(D+"/Shared Yacht Yard Atlas.mat");File.WriteAllText("FinalEnvironmentRoadReview/YachtSurfaceRepairReport.txt","SUCCESS corrected meshes="+meshes+" reversed inward faces="+flipped+"; stable per-face physical UVs; vertical single-board grain on posts; continuous rope/metal projection; lamp glass emission retained; original Yatch_Port main mesh untouched; one atlas/material and prefab LODs retained; shader errors="+ShaderUtil.GetShaderMessages(material.shader).Count(m=>m.severity.ToString()=="Error"));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/YachtSurfaceRepairReport.txt","FAILED "+e);Debug.LogException(e);}}
}
